tasks.check:
set -e
[ -e .venv ] || ln -s /home/bcorfman/dev/freytag-forge/.venv .venv
export PYTHONPATH=$PWD TMPDIR=/tmp
PY=.venv/bin/python
for f in $(git status --porcelain | grep -v '\.venv' | sed 's/^...//'); do
  [ "$f" = "tests/test_required_storylet_closure.py" ] || { echo "WHY: edited file outside ownership: $f"; exit 1; }
done
grep -q '"SL-2A-D", "SL-2B-D", "SL-2C-C", "SL-2C-D", "SL-2C-E"} <= required' tests/test_required_storylet_closure.py || { echo "WHY: required assertion must name SL-2A-D, SL-2B-D, SL-2C-C, SL-2C-D, SL-2C-E"; exit 1; }
grep -q '"SL-2C-C",' tests/test_required_storylet_closure.py || { echo "WHY: SL-2C-C missing from the present-storylets set"; exit 1; }
grep -n 'SL-2C-C' tests/test_required_storylet_closure.py | grep "not {" && { echo "WHY: SL-2C-C still in the cut set"; exit 1; } || true
git diff HEAD --numstat -- tests/test_required_storylet_closure.py | awk '{ if ($1+$2 > 8) { print "WHY: diff larger than expected: " $1+$2; exit 1 } }'
$PY -m pytest -q -n0 -p no:cacheprovider tests/test_required_storylet_closure.py > /tmp/r9.log 2>&1 || { tail -25 /tmp/r9.log; echo "WHY: test file fails"; exit 1; }
tail -2 /tmp/r9.log
$PY -m ruff format --check tests/test_required_storylet_closure.py && $PY -m ruff check tests/test_required_storylet_closure.py || { echo "WHY: ruff"; exit 1; }
OUT=/home/bcorfman/dev/ringer-work/act2-2c-yes
mkdir -p $OUT && git add -A >/dev/null 2>&1 && git diff --cached > $OUT/r9.patch && wc -l $OUT/r9.patch && git diff --cached --stat | tail -3
